<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\File;
class Backup {
 public const TABLES=['users','categories','products','product_variants','product_images','shipping_rules','discount_codes','orders','order_items','payment_attempts','inventory_reservations','stock_movements','shipments','site_settings','audit_logs'];
 public function create():string {$dir=config('maro.backup_dir');File::ensureDirectoryExists($dir,0700);if(str_starts_with(realpath($dir),realpath(public_path())))throw new \RuntimeException('Backup path must be outside public.');$rows=DB::transaction(function(){$r=[];foreach(self::TABLES as $t)$r[$t]=DB::table($t)->get()->map(fn($row)=>(array)$row)->all();return $r;});$files=[];foreach(['uploads','originals'] as $folder)if(is_dir(storage_path('app/private/'.$folder)))foreach(File::allFiles(storage_path('app/private/'.$folder))as $file)$files[$folder.'/'.$file->getRelativePathname()]=base64_encode(file_get_contents($file->getPathname()));$payload=['format'=>1,'at'=>now()->toIso8601String(),'tables'=>$rows,'files'=>$files];$path=$dir.'/maro-'.now()->format('Ymd-His').'-'.bin2hex(random_bytes(3)).'.backup';file_put_contents($path,Crypt::encryptString(json_encode($payload,JSON_THROW_ON_ERROR)),LOCK_EX);chmod($path,0600);$backups=glob($dir.'/maro-*.backup');rsort($backups);foreach(array_slice($backups,config('maro.backup_keep'))as $old)unlink($old);file_put_contents($dir.'/last-success.txt',now()->toIso8601String());return $path;}
 public function restore(string $path):array {if(app()->environment('production'))throw new \RuntimeException('Restore into an isolated non-production installation only.');$d=json_decode(Crypt::decryptString(file_get_contents($path)),true,512,JSON_THROW_ON_ERROR);if(($d['format']??0)!==1||array_keys($d['tables'])!==self::TABLES)throw new \RuntimeException('Unknown backup format.');foreach(self::TABLES as $t)if(DB::table($t)->exists())throw new \RuntimeException('Target must contain migrated, empty tables.');DB::transaction(function()use($d){foreach(self::TABLES as $t)foreach(array_chunk($d['tables'][$t],100)as $rows)DB::table($t)->insert($rows);});foreach($d['files']as $name=>$content){if(!preg_match('#^(uploads|originals)/[a-zA-Z0-9.\-]+$#',$name))throw new \RuntimeException('Unsafe backup filename.');$dest=storage_path('app/private/'.$name);File::ensureDirectoryExists(dirname($dest),0700);file_put_contents($dest,base64_decode($content,true));chmod($dest,0600);}return ['tables'=>count($d['tables']),'files'=>count($d['files']),'orders'=>count($d['tables']['orders'])];}
}
